<script setup>
import IncidentSupplement from './IncidentSupplement.vue'
import { computed,ref,watch } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { useDemo } from '../../stores/demo.js'
import PageHeader from '../../components/PageHeader.vue'
import StatusBadge from '../../components/StatusBadge.vue'
import { display,vesselGroups } from './fields.js'
const props=defineProps({staff:Boolean})
const store=useDemo(),route=useRoute(),router=useRouter(),error=ref(''),preview=ref(null),correctionDialog=ref(false),remarks=ref('')
const event=computed(()=>store.getEvent(route.params.id))
const prefix=computed(()=>props.staff?'/admin/incidents':'/reporter/reports')
const tab=computed({get:()=>route.query.tab||'overview',set:value=>router.replace({query:{...route.query,tab:value}})})
const tabs=computed(()=>['overview','vessels','consequences','evidence','chronology','reports',...(props.staff?['enforcement','actions','lineage']:[])])
watch(()=>route.query.tab,value=>{if(value&&!tabs.value.includes(value))router.replace({query:{...route.query,tab:'overview'}})},{immediate:true})
const evidence=computed(()=>store.state.evidence.filter(e=>(event.value?.evidenceIds||[]).includes(e.id)||e.eventId===event.value?.id))
const reports=computed(()=>store.state.reports.filter(r=>r.eventId===event.value?.id&&(props.staff||(r.type==='spot'&&r.createdBy===event.value?.ownerId))).sort((a,b)=>(b.createdAt||'').localeCompare(a.createdAt||'')))
const cases=computed(()=>props.staff&&store.can('enforce')?store.state.cases.filter(c=>c.eventId===event.value?.id):[])
const actions=computed(()=>props.staff?store.state.actions.filter(a=>a.eventId===event.value?.id):[])
const editable=computed(()=>event.value&&(props.staff?(store.can('review',event.value)||store.can('investigate',event.value)):(store.can('report',event.value)&&['draft','correction_requested'].includes(event.value.status))))
const reviewable=computed(()=>props.staff&&event.value&&store.can('review',event.value))
const correction=computed(()=>[...(event.value?.history||[])].reverse().find(h=>h.status==='correction_requested'))
function office(id){return store.state.offices.find(o=>o.id===id)?.name||display(id)}
function transition(status){error.value='';try{if(status==='correction_requested'&&!remarks.value.trim())throw Error('Explain which information must be corrected.');store.transition(event.value.id,status,remarks.value);correctionDialog.value=false;remarks.value=''}catch(e){error.value=e.message}}
function stamp(value){return value?new Date(value).toLocaleString():'Unknown'}
</script>
<template><div class="page-wrap"><PageHeader :title="event?`${event.ref||'Draft'} · ${event.type||'Incident report'}`:'Record unavailable'" :subtitle="event?`${event.date||'Date unknown'} · ${event.place||'Location not supplied'}`:'The requested record does not exist or is outside your account scope.'"><template #actions><q-btn flat no-caps label="Back to register" :to="prefix"/><q-btn v-if="editable" color="primary" no-caps icon="edit" :label="event.status==='correction_requested'?'Respond to correction':'Edit report'" :to="`${prefix}/${event.id}/edit`"/></template></PageHeader><section v-if="!event" class="panel empty-state"><q-icon name="lock_outline" size="44px"/><p>Sign in with an authorized account to access this report.</p></section><template v-else><q-banner v-if="error" class="bg-red-1 text-negative q-mb-md" role="alert">{{error}}</q-banner><q-banner v-if="correction&&event.status==='correction_requested'" class="bg-orange-1 text-dark q-mb-md"><strong>Correction requested by {{correction.actorName}}</strong><p class="q-mb-none">{{correction.remarks}}</p><template #action><q-btn v-if="editable" flat no-caps label="Edit and resubmit" :to="`${prefix}/${event.id}/edit`"/></template></q-banner><section class="panel"><div class="toolbar-row"><StatusBadge :status="event.status"/><span class="muted">{{event.vessels.length}} vessel involvement(s) · updated {{stamp(event.updatedAt)}}</span><q-space/><q-btn v-if="reviewable&&['submitted','resubmitted'].includes(event.status)" color="primary" no-caps label="Start review" @click="transition('under_review')"/><template v-if="reviewable&&event.status==='under_review'"><q-btn outline color="primary" no-caps label="Request correction" @click="correctionDialog=true"/><q-btn color="primary" no-caps label="Validate report" @click="transition('validated')"/></template><q-btn v-if="store.can('investigate',event)" outline color="primary" no-caps label="Investigation" :to="`/admin/investigations/${event.id}`"/><q-btn v-if="!staff&&store.can('review',event)" flat color="primary" no-caps label="Review report" :to="`/admin/incidents/${event.id}`"/><q-btn v-if="!staff&&store.can('enforce',event)" flat color="primary" no-caps label="Cases and orders" :to="`/admin/cases?eventId=${event.id}`"/></div><q-tabs v-model="tab" align="left" active-color="primary" indicator-color="primary" narrow-indicator outside-arrows mobile-arrows class="q-mt-md"><q-tab v-for="item in tabs" :key="item" :name="item" :label="item" no-caps/></q-tabs></section>
 <section v-if="tab==='overview'" class="panel q-mt-md"><h2 class="section-title">Occurrence</h2><div class="form-grid"><div v-for="[label,value] in [['Date',event.dateUnknown?'Unknown':event.date],['Local time',event.timeUnknown?'Unknown':event.time],['Initial Event',event.type],['Subsequent Event(s)',event.secondaryTypes?.join(', ')],['Level of Maritime Accident (MARINA)',event.seriousness?.replaceAll('_',' ')],['Impacts',event.impactTypes?.join(', ')],['Reported location',event.place],['Coordinate quality',event.positionQuality]]" :key="label"><div class="muted">{{label}}</div><p>{{display(value)}}</p></div><div><div class="muted">Coordinates</div><p>{{display(event.lat)}}, {{display(event.lon)}}</p></div><div v-for="[key,label] in [['aor','AOR / occurrence jurisdiction'],['homeport','Homeport'],['cpc','CPC'],['issuingOffice','Actual Issuing MRO']]" :key="key"><div class="muted">{{label}}</div><p>{{office(event[key])}}</p></div></div><template v-for="[key,label] in [['summary','Factual account'],['initialActions','Initial response and actions'],['recommendations','Recommendations / further information']]" :key="key"><h3 class="section-title q-mt-lg">{{label}}</h3><p style="white-space:pre-wrap">{{display(event[key])}}</p></template><IncidentSupplement :event="event"/><q-separator/><h3 class="section-title q-mt-lg">Source and attribution</h3><div class="form-grid"><div><span class="muted">Source: </span>{{display(event.sourceType)}} · {{display(event.sourceRef)}}</div><div><span class="muted">Received: </span>{{display(event.receivedDate)}}</div><div><span class="muted">Report owner: </span>{{store.state.users.find(u=>u.id===event.ownerId)?.name||event.ownerId}}</div><div><span class="muted">Account office: </span>{{office(event.officeId)}}</div></div></section>
 <section v-if="tab==='vessels'" class="q-mt-md"><div v-if="!event.vessels.length" class="panel empty-state">No vessel particulars supplied.</div><q-expansion-item v-for="(v,i) in event.vessels" :key="i" :label="`${i+1}. ${v.name||'Unnamed vessel'}`" :caption="`${v.role||'Involved vessel'} · ${display(v.grossTonnage)} GT`" icon="directions_boat" class="panel q-mb-md" :default-opened="i===0"><div v-for="group in vesselGroups" :key="group.title" class="q-mt-md"><h3 class="section-title">{{group.title}}</h3><div class="form-grid"><div v-for="[key,label] in group.fields" :key="key"><span class="muted">{{label}}: </span>{{['homeport','cpc'].includes(key)?office(v[key]):display(v[key])}}</div></div></div><h3 class="section-title q-mt-lg">Voyage and cargo</h3><div class="form-grid"><div v-for="[key,label] in [['origin','Origin'],['destination','Destination'],['route','Route'],['cargoType','Cargo type'],['cargoQuantity','Cargo quantity'],['cargoUnit','Cargo unit']]" :key="key"><span class="muted">{{label}}: </span>{{display(v.voyage?.[key])}}</div></div></q-expansion-item></section>
 <section v-if="tab==='consequences'" class="panel q-mt-md"><h2 class="section-title">Event consequences</h2><p class="muted">These event totals are counted once, regardless of vessels or report revisions. “Unknown” is distinct from a confirmed zero.</p><div class="metric-grid"><div v-for="[key,label] in [['fatalities','Fatalities'],['missing','Missing'],['injured','Injured'],['rescued','Rescued'],['totalOnboard','Total aboard'],['crew','Crew'],['passengers','Passengers']]" :key="key" class="metric-card"><div class="muted">{{label}}</div><div class="text-h5">{{event.consequences?.[key]??'Unknown'}}</div></div></div><div v-for="[key,label] in [['shipCondition','Vessel condition'],['pollution','Pollution / environmental impact'],['notes','Consequence notes']]" :key="key"><h3 class="section-title q-mt-lg">{{label}}</h3><p style="white-space:pre-wrap">{{display(event.consequences?.[key])}}</p></div></section>
 <section v-if="tab==='evidence'" class="panel q-mt-md"><h2 class="section-title">Evidence and source documents</h2><q-list v-if="evidence.length" separator><q-item v-for="e in evidence" :key="e.id"><q-item-section avatar><q-icon name="description"/></q-item-section><q-item-section><q-item-label>{{e.name}}</q-item-label><q-item-label caption>{{e.type}} · {{e.sourceRef||'No source reference'}} · {{e.status}}</q-item-label></q-item-section><q-item-section side><q-btn flat no-caps color="primary" label="View metadata" @click="preview=e"/></q-item-section></q-item></q-list><div v-else class="empty-state">No document references attached.<q-btn v-if="editable" flat color="primary" no-caps label="Edit report to attach metadata" :to="`${prefix}/${event.id}/edit`"/></div></section>
 <section v-if="tab==='chronology'" class="panel q-mt-md"><h2 class="section-title">Attributed status history</h2><q-timeline color="primary"><q-timeline-entry v-for="(h,i) in [...(event.history||[])].reverse()" :key="h.id||i" :title="h.status?.replaceAll('_',' ')" :subtitle="`${stamp(h.at)} · ${h.actorName||h.actorId||'Actor not supplied'}`"><p style="white-space:pre-wrap">{{h.remarks||'Status recorded.'}}</p></q-timeline-entry></q-timeline><p v-if="!event.history?.length" class="empty-state">No submitted history yet. Save or submit the report to record an activity.</p></section>
 <section v-if="tab==='reports'" class="panel q-mt-md"><h2 class="section-title">Submitted report revisions</h2><p class="muted">Each submitted revision is retained separately. Revisions are not additional casualty events.</p><q-list separator v-if="reports.length"><q-item v-for="report in reports" :key="report.id"><q-item-section><q-item-label>{{report.type==='spot'?'Spot report':`MAIC Form ${report.type}`}} · Revision {{report.revision}}</q-item-label><q-item-label caption>{{report.date||report.createdAt?.slice(0,10)}} · {{report.preparedBy||store.state.users.find(u=>u.id===report.createdBy)?.name||'Preparer not supplied'}}</q-item-label></q-item-section><q-item-section side><StatusBadge :status="report.status"/></q-item-section><q-item-section side><q-btn flat color="primary" no-caps label="View revision" @click="preview={...report,name:`${report.type} · revision ${report.revision}`,type:'Submitted report snapshot'}"/></q-item-section></q-item></q-list><div v-else class="empty-state">No submitted revisions. Draft content remains in the incident workspace.</div></section>
 <section v-if="staff&&tab==='enforcement'" class="panel q-mt-md"><h2 class="section-title">Linked enforcement cases</h2><p v-if="!store.can('enforce')" class="muted">Your role does not permit enforcement case access.</p><template v-else><q-list v-if="cases.length" separator><q-item v-for="c in cases" :key="c.id" clickable :to="`/admin/cases/${c.id}`"><q-item-section>{{c.caseNumber||c.id}} · {{c.party}}</q-item-section><q-item-section side><StatusBadge :status="c.status"/></q-item-section></q-item></q-list><p v-else class="empty-state">No enforcement cases linked.</p><q-btn outline no-caps color="primary" label="Open case register" :to="`/admin/cases?eventId=${event.id}`"/></template></section>
 <section v-if="staff&&tab==='actions'" class="panel q-mt-md"><h2 class="section-title">Recommendations and follow-up</h2><q-list v-if="actions.length" separator><q-item v-for="a in actions" :key="a.id" clickable :to="`/admin/actions?eventId=${event.id}`"><q-item-section>{{a.title}}<q-item-label caption>Due {{a.dueDate||'not set'}} · {{office(a.officeId)}}</q-item-label></q-item-section><q-item-section side><StatusBadge :status="a.status"/></q-item-section></q-item></q-list><p v-else class="empty-state">No assigned follow-up actions.</p><q-btn outline no-caps color="primary" label="Open follow-up register" :to="`/admin/actions?eventId=${event.id}`"/></section>
 <section v-if="staff&&tab==='lineage'" class="panel q-mt-md"><h2 class="section-title">Source lineage</h2><div class="form-grid"><div v-for="[key,label] in [['file','Source file'],['sheet','Worksheet'],['row','Source row'],['mergeGroup','Event merge group']]" :key="key"><span class="muted">{{label}}: </span>{{display(event.sourceLineage?.[key])}}</div></div><p class="muted q-mt-md">Manually entered events may have no import row. Synthetic source references demonstrate traceability.</p><q-btn v-if="store.can('analyze')" outline color="primary" no-caps label="Open reconciliation" :to="`/admin/reconciliation?eventId=${event.id}`"/></section>
 </template><q-dialog v-model="correctionDialog"><q-card style="width:560px;max-width:95vw"><q-card-section class="text-h6">Request reporter correction</q-card-section><q-card-section><q-input v-model="remarks" type="textarea" outlined label="Required corrections *" autogrow/><q-banner v-if="error" class="text-negative q-mt-md">{{error}}</q-banner></q-card-section><q-card-actions align="right"><q-btn flat no-caps label="Cancel" v-close-popup/><q-btn color="primary" no-caps label="Send correction request" @click="transition('correction_requested')"/></q-card-actions></q-card></q-dialog><q-dialog :model-value="!!preview" @update:model-value="preview=null"><q-card style="width:740px;max-width:95vw"><q-card-section class="row items-center"><strong class="text-h6">{{preview?.name}}</strong><q-space/><q-btn flat round icon="close" v-close-popup aria-label="Close preview"/></q-card-section><q-card-section><p class="muted">Local demonstration metadata / retained report snapshot. File contents are not uploaded.</p><div v-for="[key,value] in Object.entries(preview||{}).filter(([k])=>!['fields','id'].includes(k))" :key="key" class="q-mb-sm"><strong>{{key}}: </strong>{{typeof value==='object'?JSON.stringify(value):display(value)}}</div><template v-if="preview?.fields"><h3 class="section-title">Retained submission fields</h3><pre class="snapshot-preview">{{JSON.stringify(preview.fields,null,2)}}</pre></template></q-card-section><q-card-actions align="right"><q-btn flat no-caps label="Close" v-close-popup/></q-card-actions></q-card></q-dialog></div></template>
<style scoped>.snapshot-preview{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px;max-height:50vh;overflow:auto}</style>
